-- Catálogo bilíngue 9/10, parte 3/4 (500 palavras). Execute as quatro partes em ordem.
-- Reexecutável: atualiza definition_pt e example_pt de palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"chiton","translation":"quíton","definition_en":"A woolen or linen tunic worn by both men and women in ancient Greece, typically fastened at the shoulders.","definition_pt":"Uma túnica de lã ou linho usada por homens e mulheres na Grécia antiga, tipicamente presa nos ombros.","example_en":"The ancient Greek woman wore a simple chiton made of linen.","example_pt":"A grega antiga usava um simples chiton feito de linho.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chive","translation":"cebolinha","definition_en":"A perennial plant with long, thin, hollow green leaves used as a mild onion-flavored seasoning in cooking.","definition_pt":"Uma planta perene com folhas verdes longas, finas e ocas usadas como tempero suave com sabor de cebola na cozinha.","example_en":"She sprinkled fresh chives over the baked potato.","example_pt":"Ela aspergiu cebolinhos frescos sobre a batata assada.","cefr_level":"A2","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"chloramphenicol","translation":"cloranfenicol","definition_en":"An oral antibiotic used to treat serious bacterial infections, such as typhoid fever and meningitis.","definition_pt":"Um antibiótico oral usado para tratar infecções bacterianas graves, como febre tifóide e meningite.","example_en":"The doctor prescribed chloramphenicol for the severe infection.","example_pt":"O médico receitou cloranfenicol para a infecção grave.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"chlorate","translation":"clorato","definition_en":"A chemical compound containing the chlorate ion (ClO3-), typically a salt formed from chloric acid.","definition_pt":"Um composto químico contendo o íon clorato (ClO3-), tipicamente um sal formado a partir de ácido clorídrico.","example_en":"Potassium chlorate is used in fireworks and safety matches.","example_pt":"O clorato de potássio é usado em fogos de artifício e fósforos de segurança.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chlorofluorocarbon","translation":"clorofluorocarboneto","definition_en":"A fluorocarbon compound containing chlorine, formerly used as a refrigerant and as a propellant in aerosol cans, known to deplete the ozone layer.","definition_pt":"Um composto de fluorocarboneto contendo cloro, anteriormente usado como refrigerante e como um propulsor em latas de aerossol, conhecido por esgotar a camada de ozônio.","example_en":"Chlorofluorocarbons were widely used in air conditioning systems until their environmental impact was discovered.","example_pt":"Clorofluorocarbonetos foram amplamente usados em sistemas de ar condicionado até que seu impacto ambiental foi descoberto.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chloroplast","translation":"cloroplasto","definition_en":"A plastid found in plant cells and some algae that contains chlorophyll and is responsible for photosynthesis.","definition_pt":"Um plastídeo encontrado em células vegetais e algumas algas que contém clorofila e é responsável pela fotossíntese.","example_en":"Chloroplasts convert sunlight into chemical energy during photosynthesis.","example_pt":"Cloroplastos convertem a luz solar em energia química durante a fotossíntese.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chloroquine","translation":"cloroquina","definition_en":"A medication used to prevent and treat malaria, and also sometimes used for autoimmune conditions like lupus.","definition_pt":"Um medicamento usado para prevenir e tratar malária, e também usado para doenças autoimunes como lúpus.","example_en":"The doctor prescribed chloroquine for the patient's malaria infection.","example_pt":"O médico receitou cloroquina para a infecção da malária.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"chlorosis","translation":"clorose","definition_en":"A condition in young women characterized by weakness, menstrual disturbances, and a greenish tint to the skin, caused by a lack of iron.","definition_pt":"Uma condição em mulheres jovens caracterizada por fraqueza, distúrbios menstruais, e um tom esverdeado na pele, causada por falta de ferro.","example_en":"The patient was diagnosed with chlorosis after presenting with fatigue and a pale green complexion.","example_pt":"O paciente foi diagnosticado com clorose após apresentar fadiga e uma pele verde pálida.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"chokehold","translation":"mata-leão","definition_en":"A physical grappling technique where one person wraps their arm around another's neck from behind, applying pressure to restrict breathing or blood flow.","definition_pt":"Uma técnica física de luta onde uma pessoa envolve o braço ao redor do pescoço de outra por trás, aplicando pressão para restringir a respiração ou o fluxo sanguíneo.","example_en":"The police officer used a chokehold to subdue the suspect.","example_pt":"O policial usou um estrangulamento para subjugar o suspeito.","cefr_level":"B2","word_type":"noun","category_slug":"sports","frequency_rank":null},
{"word":"cholecystectomy","translation":"colecistectomia","definition_en":"A medical procedure to remove the gallbladder, typically performed to relieve pain caused by gallstones.","definition_pt":"Um procedimento médico para remover a vesícula biliar, tipicamente realizado para aliviar a dor causada por cálculos biliares.","example_en":"The patient underwent a cholecystectomy to treat chronic gallstone pain.","example_pt":"O paciente foi submetido a colecistectomia para tratar dor crônica de cálculos biliares.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"cholecystitis","translation":"colecistite","definition_en":"A medical condition characterized by swelling and irritation of the gallbladder, often caused by gallstones blocking the bile duct.","definition_pt":"Uma doença caracterizada por inchaço e irritação da vesícula biliar, causada por cálculos biliares bloqueando o ducto biliar.","example_en":"The patient was diagnosed with acute cholecystitis after experiencing severe abdominal pain.","example_pt":"O paciente foi diagnosticado com colecistite aguda após sofrer dor abdominal intensa.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"cholecystokinin","translation":"colecistoquinina","definition_en":"A hormone produced in the small intestine that stimulates the release of digestive enzymes from the pancreas and the contraction of the gallbladder to release bile.","definition_pt":"Um hormônio produzido no intestino delgado que estimula a liberação de enzimas digestivas do pâncreas e a contração da vesícula biliar para liberar a bile.","example_en":"Cholecystokinin is released when fatty acids and amino acids enter the small intestine.","example_pt":"Colecistocinina é liberada quando ácidos graxos e aminoácidos entram no intestino delgado.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"choler","translation":"cólera","definition_en":"A powerful feeling of anger or resentment, often directed at a perceived wrong.","definition_pt":"Um sentimento poderoso de raiva ou ressentimento, muitas vezes direcionado para um erro percebido.","example_en":"The injustice stirred a deep choler within the crowd.","example_pt":"A injustiça agitou um profundo enfadonho na multidão.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"choline","translation":"colina","definition_en":"A water-soluble nutrient that is part of the B-complex vitamin group, crucial for fat metabolism, liver function, and brain development.","definition_pt":"Um nutriente solúvel em água que faz parte do grupo vitamina B, crucial para o metabolismo da gordura, função hepática e desenvolvimento cerebral.","example_en":"Eggs are a rich dietary source of choline.","example_pt":"Ovos são uma rica fonte dietética de colina.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chondrite","translation":"condrito","definition_en":"A stony meteorite that contains small spherical structures called chondrules, formed in the early solar system.","definition_pt":"Um meteorito pedregoso que contém pequenas estruturas esféricas chamadas condrulas, formadas no sistema solar primitivo.","example_en":"The scientist identified the rock as a chondrite due to its distinct chondrules.","example_pt":"O cientista identificou a rocha como um condrito devido aos seus côndrulos distintos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chondritic","translation":"condrítico","definition_en":"Describes a texture or composition characteristic of chondrites, which are stony meteorites containing small, spherical silicate granules called chondrules.","definition_pt":"Descreve uma textura ou composição característica de condritos, que são meteoritos pedregosos contendo pequenos grânulos de silicato esférico chamados condrulas.","example_en":"The rock sample exhibited a chondritic texture under the microscope.","example_pt":"A amostra de rocha exibiu uma textura condrítica sob o microscópio.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"chondrule","translation":"côndrulo","definition_en":"A small, spherical granule, often composed of silicate minerals, found embedded in certain types of meteorites.","definition_pt":"Um pequeno grânulo esférico, composto frequentemente de minerais silicatos, encontrado em certos tipos de meteoritos.","example_en":"The meteorite sample contained numerous chondrules, indicating its primitive origin.","example_pt":"A amostra de meteorito continha numerosos côndrulos, indicando sua origem primitiva.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chorale","translation":"coral","definition_en":"A dignified hymn melody, particularly associated with Lutheran church music.","definition_pt":"Uma melodia digna, particularmente associada com música luterana da igreja.","example_en":"The congregation sang a beautiful chorale during the service.","example_pt":"A congregação cantou um belo coral durante o culto.","cefr_level":"B2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"chorally","translation":"coralmente","definition_en":"Performed or sung by a group of singers together, as a choir.","definition_pt":"Apresentado ou cantado por um grupo de cantores juntos, como um coral.","example_en":"The hymn was sung chorally during the service.","example_pt":"O hino foi cantado coralmente durante o serviço.","cefr_level":"B2","word_type":"adverb","category_slug":"arts","frequency_rank":null},
{"word":"chordate","translation":"cordado","definition_en":"Of or relating to the phylum Chordata, which includes animals that at some stage in their development have a notochord, a dorsal hollow nerve cord, and pharyngeal slits.","definition_pt":"Ou relacionado ao filo Chordata, que inclui animais que em algum estágio do desenvolvimento têm um notocórdio, um cordão nervoso dorsal oco e fendas faríngeas.","example_en":"The chordate nervous system is a key feature of the phylum.","example_pt":"O sistema nervoso de corda é uma característica chave do filo.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"chorea","translation":"coreia","definition_en":"Any of several degenerative nervous disorders in humans marked by irregular, spasmodic, and involuntary movements of the body and limbs.","definition_pt":"Qualquer uma das várias desordens nervosas degenerativas em humanos marcadas por movimentos irregulares, espasmódicos e involuntários do corpo e membros.","example_en":"Huntington's disease is a well-known form of chorea that affects both movement and cognition.","example_pt":"A doença de Huntington é uma forma bem conhecida de coreia que afeta tanto o movimento quanto a cognição.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"choreograph","translation":"coreografar","definition_en":"To design and arrange a sequence of movements and steps for a dance performance, typically set to music.","definition_pt":"Para projetar e organizar uma sequência de movimentos e passos para uma performance de dança, tipicamente ajustada para a música.","example_en":"She was hired to choreograph the ballet for the new production.","example_pt":"Ela foi contratada para coreografar o balé para a nova produção.","cefr_level":"B2","word_type":"verb","category_slug":"arts","frequency_rank":null},
{"word":"chorion","translation":"cório","definition_en":"The outermost membrane surrounding the embryo in reptiles, birds, and mammals, which contributes to the formation of the placenta in mammals.","definition_pt":"A membrana mais externa que envolve o embrião em répteis, pássaros e mamíferos, que contribui para a formação da placenta em mamíferos.","example_en":"The chorion is one of the extraembryonic membranes that protect the developing embryo.","example_pt":"O corião é uma das membranas extraembriônicas que protegem o embrião em desenvolvimento.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chorister","translation":"corista","definition_en":"A person who sings in a choir, especially a church choir.","definition_pt":"Uma pessoa que canta em um coro, especialmente em um coro da igreja.","example_en":"The chorister practiced the hymn every evening.","example_pt":"O corista praticava o hino todas as noites.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chrism","translation":"crisma","definition_en":"A sacred mixture of olive oil and balsam, blessed by a bishop, used in certain Christian ceremonies such as baptism, confirmation, and ordination.","definition_pt":"Uma mistura sagrada de azeite e bálsamo, abençoado por um bispo, usado em certas cerimônias cristãs, como batismo, confirmação e ordenação.","example_en":"The priest anointed the infant with chrism during the baptism.","example_pt":"O padre ungiu o bebê com crisma durante o batismo.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"christological","translation":"cristológico","definition_en":"Pertaining to the theological study of the nature, person, and role of Jesus Christ.","definition_pt":"Pertendo-se ao estudo teológico da natureza, pessoa e papel de Jesus Cristo.","example_en":"The Christological debates of the early church shaped Christian doctrine.","example_pt":"Os debates cristológicos da Igreja primitiva moldaram a doutrina cristã.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chromate","translation":"cromato","definition_en":"A chemical compound containing the chromate ion (CrO₄²⁻), typically derived from chromic acid.","definition_pt":"Um composto químico contendo o íon cromato (CrO42-), tipicamente derivado do ácido crômico.","example_en":"Potassium chromate is used as a laboratory reagent.","example_pt":"Cromato de potássio é usado como reagente de laboratório.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chromatic","translation":"cromático","definition_en":"Relating to or produced by color, or having the ability to refract light without separating it into spectral colors.","definition_pt":"Relacionando ou produzido pela cor, ou tendo a capacidade de refratar a luz sem separá-la em cores espectrais.","example_en":"The lens is designed to be chromatic, minimizing color distortion.","example_pt":"A lente foi projetada para ser cromática, minimizando a distorção de cor.","cefr_level":"C1","word_type":"adjective","category_slug":"arts","frequency_rank":null},
{"word":"chromaticity","translation":"cromaticidade","definition_en":"The quality of a color determined by its dominant wavelength and purity, independent of its brightness.","definition_pt":"A qualidade de uma cor determinada por seu comprimento de onda e pureza dominantes, independente de seu brilho.","example_en":"The chromaticity of the light source was measured using a spectrometer.","example_pt":"A cromaticidade da fonte de luz foi medida usando um espectrômetro.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chromatid","translation":"cromátide","definition_en":"One of the two identical copies of a chromosome that are joined together by a centromere and separate during cell division.","definition_pt":"Uma das duas cópias idênticas de um cromossomo que são unidos por um centromere e separados durante a divisão celular.","example_en":"During prophase, each chromosome consists of two sister chromatids.","example_pt":"Durante a profase, cada cromossomo consiste em duas cromatidas irmãs.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chromatin","translation":"cromatina","definition_en":"The stainable material within a cell nucleus, composed of DNA, RNA, and proteins, which condenses into chromosomes during cell division.","definition_pt":"O material colorizável dentro de um núcleo celular, composto de DNA, RNA e proteínas, que se condensa em cromossomos durante a divisão celular.","example_en":"Chromatin is essential for packaging DNA inside the nucleus.","example_pt":"A cromatina é essencial para empacotar DNA dentro do núcleo.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chromatography","translation":"cromatografia","definition_en":"A laboratory method used to separate mixtures based on differences in how components move through a stationary phase.","definition_pt":"Um método de laboratório usado para separar misturas baseado em diferenças em como os componentes se movem através de uma fase estacionária.","example_en":"The chemist used chromatography to analyze the ink composition.","example_pt":"O químico usou cromatografia para analisar a composição da tinta.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chromite","translation":"cromita","definition_en":"A brownish-black mineral composed of iron magnesium chromium oxide, which is the primary ore of chromium.","definition_pt":"Um mineral preto-acastanhado composto de ferro de óxido de cromo de magnésio, que é o minério primário de cromo.","example_en":"Chromite is mined extensively in South Africa and Kazakhstan.","example_pt":"A crimite é muito explorada na África do Sul e no Cazaquistão.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"chromolithography","translation":"cromolitografia","definition_en":"A method of printing using multiple lithographic stones or plates, each applying a different color to produce a full-color image.","definition_pt":"Um método de impressão usando várias pedras litografias ou placas, cada uma aplicando uma cor diferente para produzir uma imagem de cor completa.","example_en":"The museum displayed a rare chromolithography from the 19th century.","example_pt":"O museu exibiu uma rara cromolitografia do século 19.","cefr_level":"C2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"chromosomal","translation":"cromossômico","definition_en":"Pertaining to or characteristic of a chromosome, the thread-like structure in cells that carries genetic information.","definition_pt":"Pertencia ou característica de um cromossomo, a estrutura de fios em células que carregam informações genéticas.","example_en":"Chromosomal abnormalities can lead to genetic disorders.","example_pt":"Anomalias cromossômicas podem levar a distúrbios genéticos.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"chromosphere","translation":"cromósfera","definition_en":"A reddish, gaseous layer of the sun's atmosphere located between the photosphere and the corona, visible as a bright ring during a total solar eclipse.","definition_pt":"Uma camada gasosa avermelhada da atmosfera solar localizada entre a fotosfera e a coroa, visível como um anel brilhante durante um eclipse solar total.","example_en":"During the total eclipse, the chromosphere appeared as a thin, pinkish arc around the moon's silhouette.","example_pt":"Durante o eclipse total, a cromosfera apareceu como um arco fino e rosado em torno da silhueta da lua.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chronograph","translation":"cronógrafo","definition_en":"An instrument or device designed to accurately measure and record time intervals, often used in sports, science, and aviation.","definition_pt":"Um instrumento ou dispositivo projetado para medir e registrar com precisão intervalos de tempo, frequentemente usados em esportes, ciência e aviação.","example_en":"The pilot used a chronograph to time the flight duration.","example_pt":"O piloto usou um cronógrafo para cronometrar a duração do voo.","cefr_level":"B2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"chronologically","translation":"cronologicamente","definition_en":"In a way that follows the order in which events occurred, from earliest to latest.","definition_pt":"De uma forma que segue a ordem em que os eventos ocorreram, desde o início até o último.","example_en":"The events are listed chronologically in the report.","example_pt":"Os eventos estão listados cronologicamente no relatório.","cefr_level":"C2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chronology","translation":"cronologia","definition_en":"The arrangement of events in the order they happened over time.","definition_pt":"O arranjo dos eventos na ordem que aconteceram com o tempo.","example_en":"The book presents a clear chronology of the war.","example_pt":"O livro apresenta uma cronologia clara da guerra.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chronometer","translation":"cronômetro","definition_en":"An exceptionally accurate timepiece, especially used for navigation at sea to determine longitude.","definition_pt":"Um relógio excepcionalmente preciso, especialmente usado para navegação no mar para determinar longitude.","example_en":"The captain relied on the chronometer to calculate the ship's position.","example_pt":"O capitão confiou no cronômetro para calcular a posição da nave.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"chrysoberyl","translation":"crisoberilo","definition_en":"A hard, rare mineral composed of beryllium aluminate, typically yellow-green in color, valued as a gemstone.","definition_pt":"Um mineral raro e duro composto de aluminato de berílio, tipicamente verde-amarelo, valorizado como uma pedra preciosa.","example_en":"The jeweler displayed a stunning chrysoberyl ring.","example_pt":"O joalheiro mostrou um anel de crisoberilo impressionante.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chrysoprase","translation":"crisoprásio","definition_en":"A green variety of chalcedony, often used as a gemstone in jewelry.","definition_pt":"Uma variedade verde de calcedônia, muitas vezes usada como pedra preciosa em jóias.","example_en":"The ring was set with a beautiful chrysoprase.","example_pt":"O anel estava com uma bela crisoprase.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chrysotherapy","translation":"auroterapia","definition_en":"The use of gold compounds or gold-containing chemicals to treat certain diseases, particularly rheumatoid arthritis.","definition_pt":"O uso de compostos de ouro ou produtos químicos contendo ouro para tratar certas doenças, particularmente artrite reumatoide.","example_en":"Chrysotherapy was once a common treatment for severe rheumatoid arthritis.","example_pt":"A crisoterapia era um tratamento comum para artrite reumatoide grave.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"chrysotile","translation":"crisotila","definition_en":"A grey or green fibrous mineral that is a source of commercial asbestos.","definition_pt":"Um mineral fibroso cinza ou verde que é uma fonte de amianto comercial.","example_en":"Chrysotile is the most common type of asbestos used in building materials.","example_pt":"Crisótil é o tipo mais comum de amianto usado em materiais de construção.","cefr_level":"C2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"chthonic","translation":"ctônico","definition_en":"Relating to or inhabiting the underworld or the interior of the earth.","definition_pt":"Relacionando-se ou habitando o submundo ou o interior da Terra.","example_en":"The ancient Greeks worshipped chthonic deities like Hades.","example_pt":"Os gregos antigos adoravam divindades ctônicas como o Hades.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"churchgoer","translation":"fiel","definition_en":"A person who habitually attends religious services at a church.","definition_pt":"Uma pessoa que frequenta missas religiosas em uma igreja.","example_en":"She is a devoted churchgoer who never misses Sunday service.","example_pt":"Ela é uma religiosa devota que nunca perde o culto de domingo.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"churlish","translation":"rústico","definition_en":"Behaving in a rude, ill-mannered, or surly way, especially in a social context.","definition_pt":"Comportar-se de forma rude, mal educada, ou mal-educada, especialmente em um contexto social.","example_en":"His churlish response to the compliment surprised everyone.","example_pt":"Sua resposta rude ao elogio surpreendeu a todos.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"chyle","translation":"quilo","definition_en":"A milky fluid composed of lymph and emulsified fats that is formed in the small intestine during the digestion of dietary fats.","definition_pt":"Um líquido leitoso composto de linfa e gorduras emulsionadas que é formado no intestino delgado durante a digestão de gorduras dietéticas.","example_en":"Chyle is absorbed by the lacteals in the small intestine.","example_pt":"Chyle é absorvido pelos lacteais no intestino delgado.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"chylomicron","translation":"quilomícron","definition_en":"A microscopic particle composed of triglycerides, cholesterol, and proteins, formed in the small intestine during fat digestion and transported via the lymphatic system into the bloodstream to deliver dietary lipids to tissues.","definition_pt":"Uma partícula microscópica composta de triglicerídeos, colesterol e proteínas, formada no intestino delgado durante a digestão de gordura e transportada através do sistema linfático para a corrente sanguínea para entregar lipídios dietéticos para os tecidos.","example_en":"After a fatty meal, chylomicrons are released into the lymphatic system.","example_pt":"Depois de uma refeição gordurosa, os quilomícrons são liberados para o sistema linfático.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"chyme","translation":"quimo","definition_en":"A thick, semi-fluid mixture of partially digested food and digestive juices that moves from the stomach into the small intestine.","definition_pt":"Uma mistura espessa e semi-fluida de alimentos parcialmente digeridos e sucos digestivos que se movem do estômago para o intestino delgado.","example_en":"After the stomach churns the food, it becomes chyme.","example_pt":"Depois que o estômago faz a comida, ele se torna quime.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"cicatrise","translation":"cicatrizar","definition_en":"To heal and form a scar over a wound or injury.","definition_pt":"Para curar e formar uma cicatriz sobre uma ferida ou lesão.","example_en":"The wound began to cicatrise after several weeks of treatment.","example_pt":"A ferida começou a cicatrizar após várias semanas de tratamento.","cefr_level":"C2","word_type":"verb","category_slug":"health","frequency_rank":null},
{"word":"cicerone","translation":"cicerone","definition_en":"A person who guides and informs visitors or sightseers, especially through a museum, gallery, or historic site.","definition_pt":"Uma pessoa que guia e informa visitantes ou visitantes, especialmente através de um museu, galeria ou local histórico.","example_en":"The cicerone explained the history of each painting in the gallery.","example_pt":"A cicerona explicou a história de cada pintura na galeria.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cigarillo","translation":"cigarrilha","definition_en":"A small, narrow cigar that is often wrapped in tobacco leaves rather than paper, similar in size to a cigarette but made entirely of tobacco.","definition_pt":"Um pequeno charuto estreito que é muitas vezes enrolado em folhas de tabaco em vez de papel, similar em tamanho a um cigarro, mas feito inteiramente de tabaco.","example_en":"He lit a cigarillo after dinner.","example_pt":"Ele acendeu uma cigarrilha depois do jantar.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cilium","translation":"cílio","definition_en":"A microscopic, hair-like structure extending from the surface of many types of cells, used for movement or sensing the environment.","definition_pt":"Uma estrutura microscópica, tipo cabelo, que se estende da superfície de muitos tipos de células, usada para movimento ou para sentir o ambiente.","example_en":"The cilia in the respiratory tract help move mucus out of the lungs.","example_pt":"Os cílios no trato respiratório ajudam a tirar muco dos pulmões.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"cinchona","translation":"quina","definition_en":"The bark of cinchona trees, which is used to produce quinine and quinidine, drugs used to treat malaria and other conditions.","definition_pt":"A casca de árvores de cinchona, que é usada para produzir quinina e quinidina, drogas usadas para tratar malária e outras condições.","example_en":"Cinchona bark was historically used to treat fevers.","example_pt":"Lacre de Cinchona foi historicamente usado para tratar febres.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"cinnabar","translation":"cinabre","definition_en":"A heavy, reddish mineral composed of mercuric sulfide, which is the primary ore from which mercury is extracted.","definition_pt":"Um mineral pesado, avermelhado, composto de sulfureto de mercúrico, que é o minério primário do qual o mercúrio é extraído.","example_en":"Cinnabar has been mined for centuries to produce mercury.","example_pt":"Cinnabar foi minado por séculos para produzir mercúrio.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"circumcise","translation":"circuncidar","definition_en":"The surgical removal of the foreskin from the penis, commonly performed on male infants or adolescents for religious, cultural, or medical reasons.","definition_pt":"A remoção cirúrgica do prepúcio do pênis, comumente realizada em bebês ou adolescentes por razões religiosas, culturais ou médicas.","example_en":"Many parents decide to circumcise their newborn sons for religious reasons.","example_pt":"Muitos pais decidem circuncidar seus filhos recém-nascidos por razões religiosas.","cefr_level":"B2","word_type":"verb","category_slug":"health","frequency_rank":null},
{"word":"circumflex","translation":"circunflexo","definition_en":"A diacritical mark (^) placed above a vowel in some languages to indicate a special phonetic quality, such as length, contraction, or a specific tone.","definition_pt":"Uma marca diacrítica (^) colocada acima de uma vogal em algumas línguas para indicar uma qualidade fonética especial, como comprimento, contração, ou um tom específico.","example_en":"In French, the circumflex often indicates a historical loss of a letter, like in 'forêt' (forest).","example_pt":"Em francês, o circunflexo muitas vezes indica uma perda histórica de uma carta, como em 'forêt' (floresta).","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumlocution","translation":"circunlóquio","definition_en":"A roundabout or indirect way of speaking, often used to avoid saying something unpleasant or direct.","definition_pt":"Uma maneira indireta ou rotunda de falar, muitas vezes costumava evitar dizer algo desagradável ou direto.","example_en":"The witness's circumlocution frustrated the lawyer.","example_pt":"A circunlocução da testemunha frustrou o advogado.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumnavigation","translation":"circum-navegação","definition_en":"The act of traveling all the way around something, especially by ship or plane.","definition_pt":"O ato de viajar todo o caminho em torno de algo, especialmente por navio ou avião.","example_en":"Magellan's expedition completed the first circumnavigation of the globe.","example_pt":"A expedição de Magalhães completou a primeira circunavegação do globo.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumpolar","translation":"circumpolar","definition_en":"Describing a celestial body that, from a given latitude, never sets and remains visible throughout its entire daily orbit around the celestial pole.","definition_pt":"Descrevendo um corpo celestial que, de uma determinada latitude, nunca se estabelece e permanece visível durante toda sua órbita diária em torno do pólo celeste.","example_en":"In northern Canada, Polaris is a circumpolar star.","example_pt":"No norte do Canadá, Polaris é uma estrela circunpolar.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"circumscribe","translation":"delimitar","definition_en":"To limit something within certain boundaries or constraints.","definition_pt":"Para limitar algo dentro de certos limites ou restrições.","example_en":"The new law circumscribes the powers of the president.","example_pt":"A nova lei circunscreve os poderes do presidente.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumscription","translation":"circunscrição","definition_en":"The process or act of drawing a line around something, thereby limiting or confining it.","definition_pt":"O processo ou ato de traçar uma linha em torno de algo, limitando ou limitando-o.","example_en":"The circumscription of the king's power was a long and difficult process.","example_pt":"A circunscrição do poder do rei foi um processo longo e difícil.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumspect","translation":"prudente","definition_en":"Wary and unwilling to take risks; careful to consider all circumstances before acting.","definition_pt":"Cuidadoso e não disposto a correr riscos, cuidado para considerar todas as circunstâncias antes de agir.","example_en":"The diplomat was circumspect in his response to the sensitive question.","example_pt":"O diplomata foi circunspecto em sua resposta à questão sensível.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumspection","translation":"circunspeção","definition_en":"The quality of being cautious and thinking carefully before acting or speaking, especially to avoid potential problems or embarrassment.","definition_pt":"A qualidade de ser cauteloso e pensar cuidadosamente antes de agir ou falar, especialmente para evitar problemas em potencial ou constrangimento.","example_en":"He handled the sensitive topic with great circumspection.","example_pt":"Ele lidou com o assunto sensível com grande circunspecção.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"circumvolution","translation":"circunvolução","definition_en":"The action of turning, winding, or folding around a central point or axis.","definition_pt":"A ação de girar, enrolar, ou dobrar em torno de um ponto central ou eixo.","example_en":"The circumvolution of the rope around the pulley was smooth.","example_pt":"A circunvolução da corda ao redor da polia foi suave.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cirrus","translation":"cirro","definition_en":"A type of cloud composed of ice crystals, forming thin, wispy strands at high altitudes, typically between 4 and 8 miles.","definition_pt":"Um tipo de nuvem composta de cristais de gelo, formando fios finos e espasmos em altitudes elevadas, tipicamente entre 4 e 8 milhas.","example_en":"The sky was dotted with delicate cirrus clouds.","example_pt":"O céu estava cheio de delicadas nuvens de cirrus.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"citric","translation":"cítrico","definition_en":"Pertaining to or derived from citric acid, a weak organic acid found naturally in citrus fruits.","definition_pt":"Pertencia ou era derivado do ácido cítrico, um ácido orgânico fraco encontrado naturalmente em citrinos.","example_en":"The citric acid cycle is a key metabolic pathway in all aerobic organisms.","example_pt":"O ciclo do ácido cítrico é uma via metabólica chave em todos os organismos aeróbios.","cefr_level":"B2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"citrine","translation":"citrino","definition_en":"A semiprecious variety of quartz that ranges in color from pale yellow to deep golden brown, often used in jewelry.","definition_pt":"Uma variedade semipreciosa de quartzo que varia de amarelo pálido a marrom dourado profundo, muitas vezes usado em jóias.","example_en":"She wore a beautiful citrine pendant around her neck.","example_pt":"Ela usava um lindo pingente citrino no pescoço.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"citron","translation":"cidra","definition_en":"A large, thick-skinned, lemon-like fruit with a fragrant rind, often used in candied form or for its zest.","definition_pt":"Uma grande, de pele grossa, fruta parecida com limão com uma casca perfumada, muitas vezes usada em forma de conserva ou para o seu gosto.","example_en":"The citron is often preserved in sugar to make candied peel.","example_pt":"O citron é frequentemente preservado em açúcar para fazer cascas de conserva.","cefr_level":"B2","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"civet","translation":"civeta","definition_en":"A small, nocturnal, cat-like mammal native to Africa and Asia, known for secreting a musky substance used in perfumes.","definition_pt":"Um pequeno, noturno, mamífero tipo gato, nativo da África e Ásia, conhecido por secretar uma substância almíscar usada em perfumes.","example_en":"The African civet is known for its distinctive black-and-white markings.","example_pt":"A Civet africana é conhecida por suas marcas distintas em preto e branco.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"civilly","translation":"civilmente","definition_en":"In a manner that is polite, courteous, and respectful, especially in social interactions.","definition_pt":"De uma forma educada, cortês e respeitosa, especialmente nas interações sociais.","example_en":"He civilly asked for directions from the stranger.","example_pt":"Ele pediu instruções ao estranho.","cefr_level":"B2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clabber","translation":"coalhada","definition_en":"Raw milk that has naturally soured and thickened, often used in traditional cooking or as a drink.","definition_pt":"Leite cru que naturalmente azedou e engrossar, muitas vezes usado na cozinha tradicional ou como uma bebida.","example_en":"She used clabber to make a tangy, old-fashioned cheese.","example_pt":"Ela usou clabber para fazer um queijo picante e antiquado.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clade","translation":"clado","definition_en":"A group of organisms that consists of a common ancestor and all its lineal descendants, representing a single branch on the tree of life.","definition_pt":"Um grupo de organismos que consiste de um ancestral comum e todos os seus descendentes lineares, representando um único ramo na árvore da vida.","example_en":"Birds are a clade that evolved from theropod dinosaurs.","example_pt":"Os pássaros são um clado que evoluiu de dinossauros terópodes.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"cladode","translation":"cladódio","definition_en":"A flattened, leaf-like stem that performs photosynthesis, typically found in plants adapted to arid environments.","definition_pt":"Um tronco achatado, tipo folha que realiza fotossíntese, tipicamente encontrado em plantas adaptadas a ambientes áridos.","example_en":"The cactus uses its cladodes to photosynthesize and store water.","example_pt":"O cacto usa seus cladodos para fotossintese e armazenar água.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"cladogram","translation":"cladograma","definition_en":"A branching diagram showing the evolutionary relationships among groups of organisms based on shared derived characteristics.","definition_pt":"Um diagrama de ramificação mostrando as relações evolutivas entre grupos de organismos baseados em características derivadas compartilhadas.","example_en":"The biologist drew a cladogram to illustrate how birds are related to dinosaurs.","example_pt":"O biólogo desenhou um cladograma para ilustrar como as aves estão relacionadas com dinossauros.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"clairvoyance","translation":"clarividência","definition_en":"The claimed ability to gain information about an object, person, location, or physical event through extrasensory perception, without using the known human senses.","definition_pt":"A capacidade reivindicada de obter informações sobre um objeto, pessoa, localização, ou evento físico através de percepção extra-sensorial, sem usar os sentidos humanos conhecidos.","example_en":"She claimed to have clairvoyance and could see future events.","example_pt":"Ela alegou ter clarividência e podia ver eventos futuros.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clapperboard","translation":"claquete","definition_en":"A device used in filmmaking to synchronize sound and picture, consisting of a hinged board that is clapped together in front of the camera.","definition_pt":"Um dispositivo usado na produção de filmes para sincronizar som e imagem, consistindo de uma placa articulada que é aplaudida na frente da câmera.","example_en":"The director called 'action' after the clapperboard was snapped shut.","example_pt":"O diretor chamou de \"ação\" depois que o quadro foi fechado.","cefr_level":"B2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"claque","translation":"claque","definition_en":"A group of people hired to applaud or praise a performer or public speaker, often to create an impression of success.","definition_pt":"Um grupo de pessoas contratadas para aplaudir ou louvar um artista ou orador público, muitas vezes para criar uma impressão de sucesso.","example_en":"The opera singer's performance was supported by a claque in the audience.","example_pt":"A performance do cantor de ópera foi apoiada por uma claque na plateia.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clarinetist","translation":"clarinetista","definition_en":"A person who plays the clarinet, a woodwind instrument with a single-reed mouthpiece.","definition_pt":"Uma pessoa que toca clarinete, um instrumento de sopro com um bocal de uma única cor.","example_en":"The clarinetist performed a beautiful solo at the concert.","example_pt":"O clarinetista fez um belo solo no concerto.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"classicism","translation":"classicismo","definition_en":"A movement in literature and art during the 17th and 18th centuries in Europe that favored rationality, restraint, and strict forms, often inspired by ancient Greek and Roman models.","definition_pt":"Um movimento na literatura e arte durante os séculos XVII e XVIII na Europa que favoreceu a racionalidade, a contenção e formas estritas, muitas vezes inspiradas em antigos modelos gregos e romanos.","example_en":"Classicism emphasized order, balance, and clarity in artistic expression.","example_pt":"O classicismo enfatizava ordem, equilíbrio e clareza na expressão artística.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"classicist","translation":"classicista","definition_en":"An artist or writer who follows the principles of classicism, emphasizing order, balance, and simplicity in art and literature.","definition_pt":"Um artista ou escritor que segue os princípios do classicismo, enfatizando ordem, equilíbrio e simplicidade na arte e literatura.","example_en":"The painter was a dedicated classicist, favoring symmetry and harmony in his works.","example_pt":"O pintor era um classicista dedicado, favorecendo simetria e harmonia em suas obras.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"classifier","translation":"classificador","definition_en":"A word or morpheme used in some languages (e.g., Chinese, Japanese, Thai) to indicate the semantic class of a noun, often used with numbers or demonstratives.","definition_pt":"Uma palavra ou morfema usada em algumas línguas (por exemplo, chinês, japonês, tailandês) para indicar a classe semântica de um substantivo, muitas vezes usado com números ou demonstrativos.","example_en":"In Mandarin, the classifier '张' is used for flat objects like paper.","example_pt":"Em mandarim, o classificador ''' é usado para objetos planos como papel.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clastic","translation":"clástico","definition_en":"Relating to a rock that is made up of fragments or pieces of pre-existing rocks, such as conglomerates or sandstone.","definition_pt":"Relacionado a uma rocha que é composta de fragmentos ou pedaços de rochas pré-existentes, como conglomerados ou arenito.","example_en":"Clastic sedimentary rocks are formed from the accumulation of mineral and rock fragments.","example_pt":"Rochas sedimentares elásticas são formadas a partir do acúmulo de fragmentos minerais e de rochas.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"claustrophobe","translation":"claustrófobo","definition_en":"An individual who experiences an extreme or irrational fear of confined or enclosed spaces.","definition_pt":"Um indivíduo que experimenta um medo extremo ou irracional de espaços confinados ou fechados.","example_en":"As a claustrophobe, she avoids taking the elevator.","example_pt":"Como claustrofóbica, ela evita pegar o elevador.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clavichord","translation":"clavicórdio","definition_en":"A small, early keyboard instrument that produces sound by striking brass or iron strings with small metal blades called tangents. It is known for its delicate, expressive tone and dynamic control.","definition_pt":"Um pequeno instrumento de teclado que produz som por golpes de bronze ou cordas de ferro com pequenas lâminas de metal chamadas tangentes. É conhecida por seu tom delicado, expressivo e controle dinâmico.","example_en":"The musician played a Baroque piece on the clavichord.","example_pt":"O músico tocou uma peça barroca no clavichord.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"clayey","translation":"argiloso","definition_en":"Describing soil or material that has a high proportion of clay, making it sticky and dense.","definition_pt":"Descrevendo solo ou material que tem uma alta proporção de argila, tornando-o pegajoso e denso.","example_en":"The clayey soil in this region is excellent for pottery.","example_pt":"O solo argiloso nesta região é excelente para cerâmica.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cleat","translation":"grampo","definition_en":"A metal or plastic projection on the sole of a shoe, designed to prevent slipping on soft or slippery surfaces.","definition_pt":"Uma projeção de metal ou plástico na sola de um sapato, projetada para evitar escorregar em superfícies macias ou escorregadias.","example_en":"The football player's cleats dug into the grass for better traction.","example_pt":"As chuteiras do jogador de futebol cavaram na grama para uma melhor tração.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clef","translation":"clave","definition_en":"A symbol placed at the beginning of a musical staff to indicate the pitch of the notes written on it.","definition_pt":"Um símbolo colocado no início de uma pauta musical para indicar o tom das notas escritas nela.","example_en":"The treble clef is commonly used for higher-pitched instruments.","example_pt":"A clave trebo é comumente usada para instrumentos agudos.","cefr_level":"B1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"clematis","translation":"clematite","definition_en":"Any of various climbing plants of the genus Clematis, known for their showy, colorful flowers and often grown in gardens.","definition_pt":"Qualquer uma das várias plantas de escalada do gênero Clematis, conhecida por suas flores vistosas e coloridas e muitas vezes cultivadas em jardins.","example_en":"The clematis climbed up the trellis, covering it with purple blossoms.","example_pt":"Os clematis subiram pela treliça, cobrindo-a com flores roxas.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clerestory","translation":"clerestório","definition_en":"An upper part of a wall in a building, typically a church or large hall, that contains a series of windows to let in light, rising above the roof of a lower section.","definition_pt":"Uma parte superior de uma parede em um edifício, tipicamente uma igreja ou grande salão, que contém uma série de janelas para deixar entrar luz, subindo acima do telhado de uma seção inferior.","example_en":"The cathedral's clerestory allowed natural light to flood the nave.","example_pt":"O Clerestory da catedral permitiu que a luz natural inundasse a nave.","cefr_level":"C2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"cliffhanger","translation":"suspense","definition_en":"A contest or situation where the result remains unknown until the very last moment.","definition_pt":"Um concurso ou situação onde o resultado permanece desconhecido até o último momento.","example_en":"The election was a real cliffhanger, with the winner decided by only a few votes.","example_pt":"A eleição foi um verdadeiro fracasso, com o vencedor decidido por apenas alguns votos.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"climacteric","translation":"climatério","definition_en":"The period in a woman's life when menstruation ceases, marking the end of reproductive ability; the menopause transition.","definition_pt":"O período na vida de uma mulher quando a menstruação cessa, marcando o fim da capacidade reprodutiva, a transição da menopausa.","example_en":"The climacteric typically occurs between the ages of 45 and 55.","example_pt":"O climatério ocorre entre 45 e 55 anos.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"climatologist","translation":"climatologista","definition_en":"A scientist who studies climate, including long-term weather patterns, climate change, and their effects on the environment.","definition_pt":"Um cientista que estuda o clima, incluindo padrões climáticos de longo prazo, mudanças climáticas, e seus efeitos no meio ambiente.","example_en":"The climatologist presented new data on global warming trends.","example_pt":"O climatologista apresentou novos dados sobre as tendências do aquecimento global.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"climatology","translation":"climatologia","definition_en":"The scientific study of climate, including long-term weather patterns, their causes, and their effects on the environment.","definition_pt":"O estudo científico do clima, incluindo padrões climáticos de longo prazo, suas causas, e seus efeitos no ambiente.","example_en":"Climatology helps us understand global warming trends.","example_pt":"A climatologia nos ajuda a entender as tendências do aquecimento global.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"clinker","translation":"clínquer","definition_en":"A hard, stony fragment of incombustible material left after burning wood, coal, or charcoal.","definition_pt":"Um fragmento duro e pedregoso de material incombustível deixado após queimar madeira, carvão ou carvão.","example_en":"The fireplace was full of clinker after the fire died down.","example_pt":"A lareira estava cheia de clinker depois que o fogo se apagou.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clinometer","translation":"inclinômetro","definition_en":"An instrument used by surveyors to measure angles of slope, elevation, or inclination of an object relative to gravity.","definition_pt":"Um instrumento usado por topógrafos para medir ângulos de inclinação, elevação ou inclinação de um objeto em relação à gravidade.","example_en":"The surveyor used a clinometer to measure the slope of the hill.","example_pt":"O topógrafo usou um clinômetro para medir a inclinação da colina.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"cloaca","translation":"cloaca","definition_en":"A chamber in birds, reptiles, amphibians, most fish, and monotremes into which the digestive, urinary, and reproductive tracts empty.","definition_pt":"Uma câmara em pássaros, répteis, anfíbios, a maioria dos peixes, e monotremes em que os tratos digestivos, urinários e reprodutivos vazios.","example_en":"In birds, the cloaca serves as the common opening for excretion and reproduction.","example_pt":"Nos pássaros, a cloaca serve como a abertura comum para excreção e reprodução.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"clockmaker","translation":"relojoeiro","definition_en":"A person whose job is to make, repair, or maintain clocks and watches.","definition_pt":"Uma pessoa cujo trabalho é fazer, consertar ou manter relógios e relógios.","example_en":"The clockmaker carefully repaired the antique grandfather clock.","example_pt":"O relojoeiro cuidadosamente consertava o relógio antigo do avô.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clonic","translation":"clônico","definition_en":"Relating to abnormal neuromuscular activity characterized by rapidly alternating muscle contraction and relaxation.","definition_pt":"Relacionado com atividade neuromuscular anormal caracterizada por rápida alternância da contração muscular e relaxamento.","example_en":"The patient exhibited clonic movements during the seizure.","example_pt":"O paciente exibiu movimentos clônicos durante a convulsão.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"close-fitting","translation":"justo","definition_en":"Describes clothing that fits closely and comfortably to the body, without being loose.","definition_pt":"Descreve roupas que se encaixam de perto e confortavelmente no corpo, sem estar solto.","example_en":"She wore a close-fitting dress to the party.","example_pt":"Ela usava um vestido de perto para a festa.","cefr_level":"B1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"closedown","translation":"encerramento","definition_en":"The act of ending or stopping the activities of a business, organization, or system.","definition_pt":"O ato de acabar ou parar as atividades de um negócio, organização, ou sistema.","example_en":"The factory faced a permanent closedown due to financial losses.","example_pt":"A fábrica enfrentou um fechamento permanente devido a perdas financeiras.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clotheshorse","translation":"varal","definition_en":"A frame or stand used for hanging clothes to dry or air out.","definition_pt":"Uma moldura ou suporte usado para pendurar roupas para secar ou ar para fora.","example_en":"She placed the wet shirts on the clotheshorse near the radiator.","example_pt":"Ela colocou as camisas molhadas no cavalo de roupas perto do radiador.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cloudberry","translation":"amora-branca","definition_en":"A creeping raspberry-like plant found in north temperate regions, producing yellow or orange berries.","definition_pt":"Uma planta rasteira, como framboesa, encontrada em regiões temperadas do norte, produzindo bagas amarelas ou laranjas.","example_en":"Cloudberries are often used in jams and desserts in Nordic countries.","example_pt":"Bagas de Nuvem são usadas em compotas e sobremesas em países nórdicos.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cloudburst","translation":"aguaceiro","definition_en":"A sudden and very heavy fall of rain, often short-lived.","definition_pt":"Uma chuva repentina e muito forte, muitas vezes de curta duração.","example_en":"The picnic was ruined by a sudden cloudburst.","example_pt":"O piquenique foi arruinado por um súbito turbilhão.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clubfoot","translation":"pé torto","definition_en":"A birth defect where a baby's foot is twisted out of shape or position, typically involving the ankle, heel, and toes.","definition_pt":"Um defeito de nascença onde o pé de um bebê está fora de forma ou posição, tipicamente envolvendo tornozelo, calcanhar e dedos dos pés.","example_en":"The baby was born with a clubfoot and will need treatment.","example_pt":"O bebê nasceu com um pé-de-foco e precisará de tratamento.","cefr_level":"B2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"clumsily","translation":"desajeitadamente","definition_en":"In a way that lacks skill, grace, or coordination, often resulting in accidents or mistakes.","definition_pt":"De uma forma que não tem habilidade, graça ou coordenação, muitas vezes resultando em acidentes ou erros.","example_en":"He clumsily knocked over the glass of water.","example_pt":"Ele derrubou o copo de água.","cefr_level":"B1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"clunky","translation":"desajeitado","definition_en":"Lacking grace, smoothness, or elegance in movement, design, or function.","definition_pt":"Falta de graça, suavidade, ou elegância em movimento, design ou função.","example_en":"The old software felt clunky and difficult to navigate.","example_pt":"O velho software parecia confuso e difícil de navegar.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
